// ==========================================
// Search Planner Interpreter
// Business Assistant V2.8 "Atlas"
// ==========================================

const raw = $json.output;

let plan;

try {
  plan = JSON.parse(raw);
} catch (error) {
  return [
    {
      json: {
        entity: "unknown",
        table: "unknown",
        filters: [],
        requested_fields: [],
        analytics_requested: false,
        analytics_fields: [],
        clarification: "invalid_json",
        company: null,
        limit: 50,
        sort: {
          field: "",
          direction: "desc"
        }
      }
    }
  ];
}

// ==========================================
// Normalize Entity Names
// ==========================================

const entityMap = {
  // Invoices
  invoice: "invoice",
  invoices: "invoice",
  Invoice: "invoice",
  Invoices: "invoice",

  // Receipts
  receipt: "receipt",
  receipts: "receipt",
  Receipt: "receipt",
  Receipts: "receipt",

  // Quotations
  quotation: "quotation",
  quotations: "quotation",
  quote: "quotation",
  quotes: "quotation",
  Quotation: "quotation",
  Quotations: "quotation",
  Quote: "quotation",
  Quotes: "quotation",

  // Transport Requests
  transport_request: "transport_request",
  transport_requests: "transport_request",
  "transport request": "transport_request",
  "transport requests": "transport_request",
  "Transport Request": "transport_request",
  "Transport Requests": "transport_request"
};

plan.entity = entityMap[plan.entity] || plan.entity;

// ==========================================
// Normalize Table Names
// ==========================================

const tableMap = {
  invoice: "invoices",
  receipt: "receipts",
  quotation: "quotations",
  transport_request: "transport_requests"
};

if (!plan.table || plan.table === "unknown") {
  plan.table = tableMap[plan.entity] || "unknown";
}

// ==========================================
// Normalize Filters
// ==========================================

const filters = Array.isArray(plan.filters)
  ? plan.filters
  : [];

// ==========================================
// Normalize Requested Fields
// ==========================================

const requestedFields = Array.isArray(plan.requested_fields)
  ? plan.requested_fields
  : [];

// ==========================================
// Normalize Analytics
// ==========================================

const analyticsRequested =
  plan.analytics_requested === true;

const analyticsFields =
  Array.isArray(plan.analytics_fields)
    ? plan.analytics_fields
    : [];

// ==========================================
// Default Sort Fields
// ==========================================

const defaultSortFields = {
  invoice: "invoice_date",
  receipt: "purchase_date",
  quotation: "quote_date",
  transport_request: "requested_date"
};

// ==========================================
// Normalize Sort
// ==========================================

let sortField = "";

let sortDirection = "desc";

if (
  plan.sort &&
  typeof plan.sort.field === "string" &&
  plan.sort.field.trim() !== ""
) {
  sortField = plan.sort.field.trim();
}

if (
  plan.sort &&
  typeof plan.sort.direction === "string" &&
  plan.sort.direction.toLowerCase() === "asc"
) {
  sortDirection = "asc";
}

// If no valid sort field was provided,
// use the correct default for the entity.

if (!sortField) {
  sortField = defaultSortFields[plan.entity] || "";
}

// ==========================================
// Normalize Limit
// ==========================================

let limit = Number(plan.limit);

if (!Number.isFinite(limit) || limit <= 0) {
  limit = 50;
}

limit = Math.floor(limit);

// ==========================================
// Final Output
// ==========================================

return [
  {
    json: {
      entity: plan.entity,

      table: plan.table,

      filters: filters,

      requested_fields:
        analyticsRequested
          ? []
          : requestedFields,

      analytics_requested:
        analyticsRequested,

      analytics_fields:
        analyticsFields,

      clarification:
        plan.clarification || null,

      company:
        plan.company || null,

      limit:
        limit,

      sort: {
        field: sortField,
        direction: sortDirection
      }
    }
  }
];

const input = $input.first().json;

const results = input.results || [];
const analytics = input.analytics || {};
const requestedFields = input.requested_fields || [];

const PAGE_SIZE = 20;
const SHOW_ALL_THRESHOLD = 20;

let displayedResults = results;
let shownResults = results.length;
let remainingResults = 0;

// Only paginate if there are more than 20 results
if (results.length > SHOW_ALL_THRESHOLD) {
  displayedResults = results.slice(0, PAGE_SIZE);
  shownResults = displayedResults.length;
  remainingResults = results.length - shownResults;
}

return [
  {
    json: {
      results: displayedResults,
      analytics,
      requested_fields: requestedFields,
      shownResults,
      totalResults: results.length,
      remainingResults
    }
  }
];

// ==========================================
// Analytics Engine
// Business Assistant V2.8 "Atlas"
// ==========================================

const planner = $('Search Planner Interpreter').first().json;

const entity = planner.entity || "unknown";

const requestedFields = Array.isArray(planner.requested_fields)
  ? planner.requested_fields
  : [];

const analyticsRequested = planner.analytics_requested === true;

const analyticsFields = Array.isArray(planner.analytics_fields)
  ? planner.analytics_fields
  : [];

const rows = $input.all();


// ==========================================
// Helpers
// ==========================================

function parseNumber(value) {

  if (value === null || value === undefined) {
    return null;
  }

  const cleaned = String(value)
    .replace(/,/g, '')
    .replace(/[^\d.-]/g, '');

  const number = parseFloat(cleaned);

  return isNaN(number) ? null : number;
}


// ==========================================
// Common Analytics
// ==========================================

const priorityCounts = {};
const statusCounts = {};

for (const item of rows) {

  const row = item.json;

  if (
    row.priority &&
    row.priority !== 'Unknown'
  ) {

    priorityCounts[row.priority] =
      (priorityCounts[row.priority] || 0) + 1;
  }

  if (
    row.status &&
    row.status !== 'Unknown'
  ) {

    statusCounts[row.status] =
      (statusCounts[row.status] || 0) + 1;
  }
}


// ==========================================
// Base Analytics Object
// ==========================================

const analytics = {

  entity,

  totalResults: rows.length,

  priorityCounts,

  statusCounts
};


// ==========================================
// Transport Requests
// ==========================================

if (
  entity === 'transport_request' ||
  entity === 'transport request'
) {

  const customerSet = new Set();

  let totalWeight = 0;
  let weightCount = 0;

  for (const item of rows) {

    const row = item.json;

    if (
      row.customer &&
      row.customer !== 'Unknown'
    ) {

      customerSet.add(row.customer);
    }

    const weight = parseNumber(row.weight);

    if (weight !== null) {

      totalWeight += weight;
      weightCount++;
    }
  }

  analytics.uniqueCustomers =
    customerSet.size;

  analytics.totalWeight =
    totalWeight;

  analytics.averageWeight =
    weightCount > 0
      ? Number((totalWeight / weightCount).toFixed(2))
      : 0;
}


// ==========================================
// Invoices
// ==========================================

if (entity === 'invoice') {

  const supplierSet = new Set();

  let totalAmount = 0;
  let amountCount = 0;

  for (const item of rows) {

    const row = item.json;

    if (
      row.supplier &&
      row.supplier !== 'Unknown'
    ) {

      supplierSet.add(row.supplier);
    }

    const amount = parseNumber(row.amount);

    if (amount !== null) {

      totalAmount += amount;
      amountCount++;
    }
  }

  analytics.uniqueSuppliers =
    supplierSet.size;

  analytics.totalAmount =
    totalAmount;

  analytics.averageAmount =
    amountCount > 0
      ? Number((totalAmount / amountCount).toFixed(2))
      : 0;
}


// ==========================================
// Receipts
// ==========================================

if (entity === 'receipt') {

  const vendorSet = new Set();

  let totalAmount = 0;
  let amountCount = 0;

  for (const item of rows) {

    const row = item.json;

    if (
      row.vendor &&
      row.vendor !== 'Unknown'
    ) {

      vendorSet.add(row.vendor);
    }

    const amount = parseNumber(row.amount);

    if (amount !== null) {

      totalAmount += amount;
      amountCount++;
    }
  }

  analytics.uniqueVendors =
    vendorSet.size;

  analytics.totalAmount =
    totalAmount;

  analytics.averageAmount =
    amountCount > 0
      ? Number((totalAmount / amountCount).toFixed(2))
      : 0;
}


// ==========================================
// Quotations
// ==========================================

if (entity === 'quotation') {

  const companySet = new Set();

  let totalAmount = 0;
  let amountCount = 0;

  for (const item of rows) {

    const row = item.json;

    if (
      row.company &&
      row.company !== 'Unknown'
    ) {

      companySet.add(row.company);
    }

    const amount = parseNumber(row.amount);

    if (amount !== null) {

      totalAmount += amount;
      amountCount++;
    }
  }

  analytics.uniqueCompanies =
    companySet.size;

  analytics.totalAmount =
    totalAmount;

  analytics.averageAmount =
    amountCount > 0
      ? Number((totalAmount / amountCount).toFixed(2))
      : 0;
}


// ==========================================
// Final Output
// ==========================================

return [
  {
    json: {

      results: rows.map(item => item.json),

      analytics,

      requested_fields: requestedFields,

      analytics_requested: analyticsRequested,

      analytics_fields: analyticsFields
    }
  }
