let sql = `
SELECT *
FROM invoices
`;

const whereClauses = [];

// ==========================================
// Field Types
// ==========================================

const numericFields = [
  'amount',
  'vat_amount'
];

const dateFields = [
  'invoice_date',
  'due_date'
];

// ==========================================
// Build WHERE Clauses
// ==========================================

for (const filter of plan.filters || []) {

  if (!filter || !filter.field || !filter.operator) {
    continue;
  }

  const field = filter.field;
  const operator = filter.operator;
  const value = filter.value;

  const isNumeric = numericFields.includes(field);
  const isDate = dateFields.includes(field);

  switch (operator) {

    // --------------------------------------
    // CONTAINS
    // --------------------------------------

    case 'contains':

      whereClauses.push(
        `${field} ILIKE '%${String(value).replace(/'/g, "''")}%'`
      );

      break;

    // --------------------------------------
    // EQUALS
    // --------------------------------------

    case 'equals':

      if (isDate) {

        whereClauses.push(
          `TO_DATE(NULLIF(${field}, 'Unknown'), 'DD FMMonth YYYY') = DATE '${value}'`
        );

      } else if (isNumeric) {

        whereClauses.push(
          `CAST(${field} AS NUMERIC) = ${Number(value)}`
        );

      } else {

        whereClauses.push(
          `${field} = '${String(value).replace(/'/g, "''")}'`
        );

      }

      break;

    // --------------------------------------
    // GREATER THAN
    // --------------------------------------

    case 'greater_than':

      if (isNumeric) {

        whereClauses.push(
          `CAST(${field} AS NUMERIC) > ${Number(value)}`
        );

      } else if (isDate) {

        whereClauses.push(
          `TO_DATE(NULLIF(${field}, 'Unknown'), 'DD FMMonth YYYY') > DATE '${value}'`
        );

      } else {

        whereClauses.push(
          `${field} > '${String(value).replace(/'/g, "''")}'`
        );

      }

      break;

    // --------------------------------------
    // LESS THAN
    // --------------------------------------

    case 'less_than':

      if (isNumeric) {

        whereClauses.push(
          `CAST(${field} AS NUMERIC) < ${Number(value)}`
        );

      } else if (isDate) {

        whereClauses.push(
          `TO_DATE(NULLIF(${field}, 'Unknown'), 'DD FMMonth YYYY') < DATE '${value}'`
        );

      } else {

        whereClauses.push(
          `${field} < '${String(value).replace(/'/g, "''")}'`
        );

      }

      break;

    // --------------------------------------
    // GREATER OR EQUAL
    // --------------------------------------

    case 'greater_or_equal':

      if (isNumeric) {

        whereClauses.push(
          `CAST(${field} AS NUMERIC) >= ${Number(value)}`
        );

      } else if (isDate) {

        whereClauses.push(
          `TO_DATE(NULLIF(${field}, 'Unknown'), 'DD FMMonth YYYY') >= DATE '${value}'`
        );

      } else {

        whereClauses.push(
          `${field} >= '${String(value).replace(/'/g, "''")}'`
        );

      }

      break;

    // --------------------------------------
    // LESS OR EQUAL
    // --------------------------------------

    case 'less_or_equal':

      if (isNumeric) {

        whereClauses.push(
          `CAST(${field} AS NUMERIC) <= ${Number(value)}`
        );

      } else if (isDate) {

        whereClauses.push(
          `TO_DATE(NULLIF(${field}, 'Unknown'), 'DD FMMonth YYYY') <= DATE '${value}'`
        );

      } else {

        whereClauses.push(
          `${field} <= '${String(value).replace(/'/g, "''")}'`
        );

      }

      break;
  }
}

// ==========================================
// Add WHERE
// ==========================================

if (whereClauses.length > 0) {

  sql += `
WHERE
${whereClauses.join('\nAND ')}
`;
}

// ==========================================
// Safe Sorting
// ==========================================

const allowedSortFields = [
  'invoice_date',
  'due_date',
  'amount',
  'supplier',
  'invoice_number'
];

let sortField = 'invoice_date';

if (
  plan.sort &&
  allowedSortFields.includes(plan.sort.field)
) {
  sortField = plan.sort.field;
}

const sortDirection =
  plan.sort &&
  typeof plan.sort.direction === 'string' &&
  plan.sort.direction.toLowerCase() === 'asc'
    ? 'ASC'
    : 'DESC';

// ==========================================
// Limit
// ==========================================

let limit = Number(plan.limit);

if (!Number.isFinite(limit) || limit <= 0) {
  limit = 50;
}

limit = Math.floor(limit);

// ==========================================
// Final SQL
// ==========================================

sql += `
ORDER BY ${sortField} ${sortDirection}
LIMIT ${limit};
`;

// ==========================================
// Extract Company / Supplier
// ==========================================

const companyFilter = (plan.filters || []).find(
  filter => filter.field === 'supplier'
);

const company = companyFilter
  ? companyFilter.value
  : null;

// ==========================================
// Final Output
// ==========================================

return [
  {
    json: {
      query: sql,
      company,
      entity: 'invoice',

      requested_fields:
        Array.isArray(plan.requested_fields)
          ? plan.requested_fields
          : [],

