SELECT *
FROM transport_requests
`;

const whereClauses = [];

const numericFields = [
    'weight'
];

const dateFields = [
    'loading_date',
    'delivery_date',
    'requested_date'
];

for (const filter of plan.filters) {

    const isNumeric = numericFields.includes(filter.field);
    const isDate = dateFields.includes(filter.field);

    switch (filter.operator) {

        case 'contains':

            whereClauses.push(
                `${filter.field} ILIKE '%${filter.value}%'`
            );

            break;

        case 'equals':

            if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') = DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} = '${filter.value}'`
                );

            }

            break;

        case 'greater_than':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(REGEXP_REPLACE(${filter.field}, '[^0-9.]', '', 'g') AS NUMERIC) > ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') > DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} > '${filter.value}'`
                );

            }

            break;

        case 'less_than':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(REGEXP_REPLACE(${filter.field}, '[^0-9.]', '', 'g') AS NUMERIC) < ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') < DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} < '${filter.value}'`
                );

            }

            break;

        case 'greater_or_equal':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(REGEXP_REPLACE(${filter.field}, '[^0-9.]', '', 'g') AS NUMERIC) >= ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') >= DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} >= '${filter.value}'`
                );

            }

            break;

        case 'less_or_equal':

            if (isNumeric) {

                whereClauses.push(
                    `CAST(REGEXP_REPLACE(${filter.field}, '[^0-9.]', '', 'g') AS NUMERIC) <= ${filter.value}`
                );

            } else if (isDate) {

                whereClauses.push(
                    `TO_DATE(NULLIF(${filter.field}, 'Unknown'), 'DD FMMonth YYYY') <= DATE '${filter.value}'`
                );

            } else {

                whereClauses.push(
                    `${filter.field} <= '${filter.value}'`
                );

            }

            break;

    }

}

if (whereClauses.length > 0) {

    sql += `
WHERE
${whereClauses.join('\nAND ')}
`;

}

sql += `
ORDER BY ${plan.sort.field} ${plan.sort.direction.toUpperCase()}
LIMIT ${plan.limit};
`;

// Extract customer/company name from planner filters
const companyFilter = plan.filters.find(
    filter => filter.field === "customer"
);

const company = companyFilter
    ? companyFilter.value
    : null;

return [
  {
    json: {
      query: sql,
      company,
      entity: "transport request",
      requested_fields: plan.requested_fields || []
    }
  }
];
